files.content:
.ds-app-shell {
  min-width: 0;
  color: var(--ui-foreground);
}
.ds-shell-body {
  min-width: 0;
}
.ds-shell-body[data-sidebar] {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  gap: clamp(24px, 4vw, 48px);
  align-items: start;
}
.ds-shell-content {
  min-width: 0;
}
.ds-shell-skip {
  position: fixed;
  top: -100px;
  left: 16px;
  padding: 12px;
  background: var(--ui-popover);
  color: var(--ui-foreground);
  z-index: var(--ui-layer-floating);
}
.ds-shell-skip:focus {
  top: 12px;
}
.ds-app-header {
  max-width: var(--ui-content-wide);
  padding-inline: var(--ui-gutter);
  margin-inline: auto;
  color: var(--ui-foreground);
}
.ds-header-main {
  display: flex;
  align-items: center;
  gap: clamp(16px, 3vw, 36px);
  min-height: 56px;
  border-bottom: 1px solid var(--ui-foreground);
}
.ds-wordmark {
  font-family: var(--ui-font-editorial);
  font-size: 28px;
  line-height: 1;
  letter-spacing: -0.045em;
  flex-shrink: 0;
}
.ds-wordmark a {
  color: inherit;
  text-decoration: none;
}
.ds-primary-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: center;
  margin-inline-start: auto;
}
.ds-primary-nav a,
.ds-primary-nav > span {
  display: flex;
  align-items: center;
  min-height: 44px;
  position: relative;
  font-size: 13px;
  text-decoration: none;
  color: inherit;
}
.ds-primary-nav a[aria-current] {
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 8px;
}
.ds-nav-disabled,
.ds-primary-nav > .ds-nav-disabled,
.ds-mobile-navigation nav > .ds-nav-disabled {
  color: var(--ui-muted-foreground);
}
.ds-header-account {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-inline-start: auto;
  font-size: 12px;
}
.ds-mobile-navigation {
  display: none;
  position: relative;
}
.ds-mobile-navigation nav:not([hidden]) {
  position: absolute;
  z-index: 20;
  inset-inline-end: 0;
  top: 100%;
  width: min(260px, calc(100vw - 2 * var(--ui-gutter)));
  max-height: calc(100dvh - 88px);
  overflow: auto;
  overscroll-behavior: contain;
  padding: 12px;
  background: var(--ui-popover);
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius);
  display: grid;
  gap: 4px;
}
.ds-mobile-navigation nav a,
.ds-mobile-navigation nav > span {
  padding: 12px;
  font-size: 13px;
  overflow-wrap: anywhere;
  color: inherit;
}
.ds-mobile-navigation nav a[aria-current] {
  font-weight: 600;
}
.ds-breadcrumbs {
  font-size: 12px;
  padding-block-start: 24px;
  color: var(--ui-muted-foreground);
}
.ds-breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 0;
  margin: 0;
  list-style: none;
}
.ds-breadcrumbs li {
  display: flex;
  gap: 10px;
  min-width: 0;
  overflow-wrap: anywhere;
}
.ds-sidebar {
  position: sticky;
  top: 24px;
  min-width: 0;
}
.ds-sidebar-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ui-muted-foreground);
}
.ds-sidebar nav {
  display: grid;
  gap: 4px;
}
.ds-sidebar nav a,
.ds-sidebar nav > span {
  font-size: 13px;
  padding: 12px;
  text-decoration: none;
  border-inline-start: 1px solid transparent;
  overflow-wrap: anywhere;
  color: inherit;
}
.ds-sidebar nav a[aria-current] {
  border-color: var(--ui-foreground);
  font-weight: 600;
  background: var(--ui-muted);
}
.ds-sidebar nav > span {
  color: var(--ui-muted-foreground);
}
.ds-section-navigation {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  margin-block: 16px;
}
.ds-section-navigation a,
.ds-section-navigation > span {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 13px;
  color: inherit;
}
.ds-section-navigation a[aria-current] {
  font-weight: 600;
  text-underline-offset: 5px;
}
.ds-section-navigation > span {
  color: var(--ui-muted-foreground);
}
.ds-app-shell :is(a, button):focus-visible,
.ds-app-header :is(a, button):focus-visible,
.ds-sidebar a:focus-visible,
.ds-section-navigation a:focus-visible,
.ds-breadcrumbs a:focus-visible {
  outline: 2px solid var(--ui-ring);
  outline-offset: 3px;
}
@media (max-width: 800px) {
  .ds-shell-body[data-sidebar] {
    grid-template-columns: minmax(0, 1fr);
  }
  .ds-sidebar {
    position: static;
  }
  .ds-sidebar nav {
    display: flex;
    flex-wrap: wrap;
  }
}
@media (max-width: 640px) {
  .ds-primary-nav {
    display: none;
  }
  .ds-mobile-navigation {
    display: block;
  }
  .ds-wordmark {
    font-size: 25px;
    overflow-wrap: anywhere;
  }
  .ds-header-main {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px 12px;
    padding-block: 12px;
  }
  .ds-header-account {
    grid-column: 1;
    grid-row: 2;
    margin-inline-start: 0;
    min-width: 0;
    overflow-wrap: anywhere;
  }
  .ds-mobile-navigation {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
}
@media print {
  .ds-app-header,
  .ds-sidebar,
  .ds-section-navigation,
  .ds-shell-skip {
    display: none;
  }
  .ds-shell-body[data-sidebar] {
    display: block;
  }
}
